const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// 1. Update CI-0006 quantity to 2
db.prepare(\"UPDATE cart_items SET quantity = 2 WHERE cart_item_id = 'CI-0006' AND cart_id = 'CART-user_58b0a2d6'\").run();

// 2. Remove CI-0005
db.prepare(\"DELETE FROM cart_items WHERE cart_item_id = 'CI-0005' AND cart_id = 'CART-user_58b0a2d6'\").run();

// 3. Recalculate subtotal from remaining items
const items = db.prepare('SELECT ci.*, p.name as product_name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?').all('CART-user_58b0a2d6');
const subtotal = items.reduce((sum, i) => sum + i.price * i.quantity, 0);
const itemIds = JSON.stringify(items.map(i => i.cart_item_id));

// 4. Update cart totals and item_ids_json
db.prepare(\"UPDATE carts SET subtotal = ?, total = ? + shipping_cost - discount_amount - loyalty_discount + gift_wrap_fee, item_ids_json = ? WHERE cart_id = 'CART-user_58b0a2d6'\").run(subtotal, subtotal, itemIds);

// 5. Fetch updated cart
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
console.log(JSON.stringify({ cart, items }, null, 2));
"

